local luassert = assert
describe("TestLuassertFixtureStrictBooleanAndTruthiness", function()
  it("test_control_strict_boolean_and_truthiness_each_hold", function()
    luassert.is_true(true)
    luassert.is_false(false)
    luassert.truthy(0)
    luassert.truthy("")
    luassert.falsy(nil)
    luassert.falsy(false)
  end)
  it("test_counterexample_strict_true_rejects_a_truthy_number", function()
    luassert.is_true(1)
  end)
end)
